// Remove only data generated by test-class-browser from the isolated local demo.
// Audits and policy history are deliberately retained as append-only records.
import { randomUUID } from "node:crypto";
import pg from "pg";
const base = new URL(process.env.DEMO_DATABASE_URL ?? "postgresql://postgres:space_agent_local_dev@127.0.0.1:55432/postgres");
if (!["127.0.0.1", "localhost"].includes(base.hostname) || base.port !== "55432") throw new Error("Cleanup is restricted to the local demo server on port 55432");
const connect = (name) => { const url=new URL(base);url.pathname=`/${name}`;return new pg.Pool({connectionString:url.toString()}); };
const classPool=connect("class_schedule"),catalogPool=connect("catalog");
const classes=await classPool.connect(),catalog=await catalogPool.connect();
try {
  await classes.query("BEGIN");
  const locked=(await classes.query("SELECT id FROM classes c WHERE code ~ '^DEMO-CLASS-[a-z0-9]+$' AND name LIKE 'DEMO · Lớp browser %' FOR UPDATE")).rows.map(r=>r.id);
  const occupied=new Set((await classes.query("SELECT DISTINCT class_id FROM holds WHERE class_id=ANY($1::uuid[]) AND (status='COMMITTED' OR (status='HELD' AND expires_at>clock_timestamp()))",[locked])).rows.map(r=>r.class_id));
  const candidates=locked.filter(id=>!occupied.has(id));
  const removedHolds=(await classes.query("DELETE FROM holds WHERE class_id=ANY($1::uuid[])",[candidates])).rowCount;
  await classes.query("DELETE FROM sessions WHERE class_id=ANY($1::uuid[])",[candidates]);
  for (const id of candidates) await classes.query("INSERT INTO class_audit(id,actor_id,action,target_id,correlation_id) VALUES($1,'local-demo-cleanup','demo.test_data_removed',$2,$3)",[randomUUID(),id,randomUUID()]);
  await classes.query("DELETE FROM classes WHERE id=ANY($1::uuid[])",[candidates]);
  await classes.query("COMMIT");
  const remaining=(await classes.query("SELECT course_id,package_id FROM classes")).rows;
  await catalog.query("BEGIN");
  const removedPackages=(await catalog.query("DELETE FROM course_packages WHERE code ~ '^DEMO-PACK-[a-z0-9]+$' AND name LIKE 'DEMO · Gói browser %' AND NOT(id=ANY($1::uuid[])) RETURNING id",[remaining.map(r=>r.package_id)])).rowCount;
  const removedCourses=(await catalog.query("DELETE FROM courses c WHERE code ~ '^DEMO-BROWSER-[a-z0-9]+$' AND name LIKE 'DEMO · Browser %' AND NOT(id=ANY($1::uuid[])) AND NOT EXISTS(SELECT 1 FROM course_packages p WHERE p.course_id=c.id) RETURNING id",[remaining.map(r=>r.course_id)])).rowCount;
  await catalog.query("COMMIT");
  console.log(JSON.stringify({removed:{classes:candidates.length,holds:removedHolds,packages:removedPackages,courses:removedCourses},preserved:"Base demo seeds, active/committed holds, manual data, audits and policy history"}));
} catch(error) { await classes.query("ROLLBACK");await catalog.query("ROLLBACK");throw error; }
finally { classes.release();catalog.release();await classPool.end();await catalogPool.end(); }
